// Generated by vibelang from src/plugin/provider/nvidia.vibe; the migrate flow writes it again with each batch.
import * as Effect from "effect/Effect";
import { define } from "@opencode/plugin/effect/plugin";
export const NvidiaPlugin = define({
    id: "opencode.provider.nvidia",
    effect: (ctx) => {
        return Effect.gen(function* effect() {
            yield* ctx.provider.transform((evt) => {
                for (const item of evt.list()) {
                    if (item.provider.package !== "@opencode/ai/providers/openai-compatible")
                        continue;
                    if (item.provider.settings?.baseURL !== "https://integrate.api.nvidia.com/v1")
                        continue;
                    evt.update(item.provider.id, (provider) => {
                        provider.headers = {
                            ...provider.headers,
                            "HTTP-Referer": "https://opencode.ai/",
                            "X-Title": "opencode",
                            "X-BILLING-INVOKE-ORIGIN": provider.headers?.["X-BILLING-INVOKE-ORIGIN"] ?? "OpenCode",
                        };
                    });
                }
            });
        });
    },
});
